def validate_scripts(scripts):
    """Validate all scripts against project rules."""
    errors = []
    forbidden_ellipsis_regex = re.compile(r"(\.{2,}|…)")
    
    for idx, s in enumerate(scripts, 1):
        s_id = s.get("id", f"script_{idx}")
        title = s.get("title", "")
        turns = s.get("turns", [])
        
        # Check turn count (target: 11-15 turns for 45-60s)
        if len(turns) < 10 or len(turns) > 16:
            errors.append(f"[{s_id}] Turn count is {len(turns)}, expected between 10 and 16.")
            
        # Check headlines
        headlines = s.get("headlines", [])
        if len(headlines) != 4:
            errors.append(f"[{s_id}] Headlines count is {len(headlines)}, expected exactly 4 scenes.")
            
        # Check ellipsis in all texts
        for t_idx, turn in enumerate(turns):
            spk, phrases, photo = turn
            for p_idx, phrase in enumerate(phrases):
                disp, spok = phrase
                if forbidden_ellipsis_regex.search(disp):
                    errors.append(f"[{s_id}] Turn {t_idx} phrase {p_idx} DISPLAY has forbidden ellipsis: '{disp}'")
                if forbidden_ellipsis_regex.search(spok):
                    errors.append(f"[{s_id}] Turn {t_idx} phrase {p_idx} SPOKEN has forbidden ellipsis: '{spok}'")
                    
        # Check hook and headlines for ellipsis
        if forbidden_ellipsis_regex.search(s.get("hook_title", "")):
            errors.append(f"[{s_id}] Hook title has forbidden ellipsis")
            
        for h in headlines:
            for field in ["sub", "t", "hl"]:
                if forbidden_ellipsis_regex.search(h.get(field, "")):
                    errors.append(f"[{s_id}] Headline field {field} has forbidden ellipsis")
                    
        # Check CTA
        if forbidden_ellipsis_regex.search(s.get("cta", "")):
            errors.append(f"[{s_id}] CTA has forbidden ellipsis")
            
    return errors

def main():
    print(f"Validating {len(SCRIPTS)} scripts...")
    errors = validate_scripts(SCRIPTS)
    if errors:
        print("Validation FAILED with errors:")
        for e in errors:
            print(" -", e)
        return False
    
    print("All 20 scripts passed validation perfectly! (Zero ellipses, correct turns)")
    
    # Save JSON
