def sync_to_products_json(scripts):
    from datetime import datetime
    products_file = DOCS / "products.json"
    if not products_file.exists():
        return
    with open(products_file, "r", encoding="utf-8") as f:
        products = json.load(f)
    p_target = next((p for p in products if p.get("id") == "9505b042d58640f5aa58015bb86be097"), None)
    if not p_target:
        return
    existing_aids = {a.get("angle_id") for a in p_target.get("angles", [])}
    now_str = datetime.now().isoformat(timespec="seconds")
    added = 0
    for s in scripts:
        aid = s["id"]
        if aid in existing_aids:
            continue
        script_text = "\n".join([
            f"{'น้องนุ้ย (F)' if t[0]=='F' else 'พี่บ่าว (M)'}: {' '.join(p[1] for p in t[1])}"
            for t in s["turns"]
        ])
        new_angle = {
            "angle_id": aid,
            "angle_name": f"💬 ละครคู่รัก: {s['title']}",
            "title": s["title"],
            "hook_title": s["hook_title"],
            "status": "script_ready",
            "draft_type": "hyperframes",
            "style": "couple_paper_chat",
            "category": s["category"],
            "scenario": s["scenario"],
            "duration": "48-55s",
            "turns_count": len(s["turns"]),
            "script_text": script_text,
            "script_lines": [p[0] for t in s["turns"] for p in t[1]],
            "headlines": s["headlines"],
            "turns": s["turns"],
            "cta": s["cta"],
            "tiktok_caption": f"{s['hook_title']} หัวชาร์จจิ๋วตัวจบ Essager PD 30W ชาร์จไวสะใจ ไม่ร้อน ปลอดภัย 6 ชั้น พิกัดในตะกร้าเหลืองเลย 👇",
            "tiktok_hashtags": "#Essager #หัวชาร์จเร็ว #หัวชาร์จไอโฟน #TikTokป้ายยา #พิกัดในตะกร้า",
            "created_at": now_str,
            "updated_at": now_str
        }
        p_target.setdefault("angles", []).append(new_angle)
        added += 1
    with open(products_file, "w", encoding="utf-8") as f:
        json.dump(products, f, ensure_ascii=False, indent=2)
    print(f"Synced {added} new angles into _Docs/products.json (Total angles: {len(p_target['angles'])})")

if __name__ == "__main__":
    main()

